import{_ as e,c as r,o as h,ah as i}from"./chunks/framework.Dnh4IO1K.js";const _=JSON.parse('{"title":"53、【渐】 艮下巽上","description":"横渠易说 - 53、【渐】 艮下巽上","frontmatter":{"title":"53、【渐】 艮下巽上","description":"横渠易说 - 53、【渐】 艮下巽上"},"headers":[],"relativePath":"zh/classics/hengqu/055.md","filePath":"zh/classics/hengqu/055.md"}'),l={name:"zh/classics/hengqu/055.md"};function t(n,a,s,d,c,o){return h(),r("div",null,[...a[0]||(a[0]=[i('<h1 id="_53、【渐】-艮下巽上" tabindex="-1">53、【渐】 艮下巽上 <a class="header-anchor" href="#_53、【渐】-艮下巽上" aria-label="Permalink to “53、【渐】 艮下巽上”">​</a></h1><h3 id="彖曰-渐之进也-女归吉也。进得位-往有功也-进以正-可以正邦也。其位-刚得中也-止而巽-动不穷也。" tabindex="-1">彖曰：渐之进也，女归吉也。进得位，往有功也；进以正，可以正邦也。其位，刚得中也；止而巽，动不穷也。 <a class="header-anchor" href="#彖曰-渐之进也-女归吉也。进得位-往有功也-进以正-可以正邦也。其位-刚得中也-止而巽-动不穷也。" aria-label="Permalink to “彖曰：渐之进也，女归吉也。进得位，往有功也；进以正，可以正邦也。其位，刚得中也；止而巽，动不穷也。”">​</a></h3><p>渐者，天地之施交。“女归吉”，“进得位”，皆指六四。施一作始。</p><h3 id="象曰-山上有木-渐-君子以居贤德善俗。" tabindex="-1">象曰：山上有木，渐，君子以居贤德善俗。 <a class="header-anchor" href="#象曰-山上有木-渐-君子以居贤德善俗。" aria-label="Permalink to “象曰：山上有木，渐，君子以居贤德善俗。”">​</a></h3><p>居可久之德，难从无征之德，君子不以责人。君子以贤德自居，不强率人，待其心回，故善俗自然。一作不可推行无征难从之德。</p><h3 id="初六-鸿渐于乾-小子厉-有言无咎。-象曰-小子之厉-义无咎也。" tabindex="-1">初六，鸿渐于乾，小子厉，有言无咎。 象曰：小子之厉，义无咎也。 <a class="header-anchor" href="#初六-鸿渐于乾-小子厉-有言无咎。-象曰-小子之厉-义无咎也。" aria-label="Permalink to “初六，鸿渐于乾，小子厉，有言无咎。 象曰：小子之厉，义无咎也。”">​</a></h3><p>鸿为水鸟，渐进之始，出至于乾。鸿鹄之志非小子所量，见其出陆，争欲危之，且疑其所处，非君子信己而行，义无咎也。</p><h3 id="六二-鸿渐于磐-饮食衎衎-吉。-象曰-饮食衎衎-不素饱也。" tabindex="-1">六二，鸿渐于磐，饮食衎衎，吉。 象曰：“饮食衎衎”，不素饱也。 <a class="header-anchor" href="#六二-鸿渐于磐-饮食衎衎-吉。-象曰-饮食衎衎-不素饱也。" aria-label="Permalink to “六二，鸿渐于磐，饮食衎衎，吉。 象曰：“饮食衎衎”，不素饱也。”">​</a></h3><p>衎衎，和乐貌。饮食和乐，不徒饱而已，言获志之多也。</p><h3 id="九三-鸿渐于陆-夫征不复-妇孕不育-凶-利御寇。-象曰-夫征不复-离群丑也-妇孕不育-失其道也-利用御寇-顺相保也。" tabindex="-1">九三，鸿渐于陆，夫征不复，妇孕不育，凶，利御寇。 象曰：“夫征不复”，离群丑也；“妇孕不育”，失其道也；“利用御寇”，顺相保也。 <a class="header-anchor" href="#九三-鸿渐于陆-夫征不复-妇孕不育-凶-利御寇。-象曰-夫征不复-离群丑也-妇孕不育-失其道也-利用御寇-顺相保也。" aria-label="Permalink to “九三，鸿渐于陆，夫征不复，妇孕不育，凶，利御寇。 象曰：“夫征不复”，离群丑也；“妇孕不育”，失其道也；“利用御寇”，顺相保也。”">​</a></h3><p>渐卦九三、六四易位而居，三离上卦，四离下体，故曰“夫征不复，妇孕不育”，然相与之固，物莫能间，故利用御寇也。“征不复”者，变为艮且得位也，如六四之得桷；三四非正合，故曰“失其道”也。</p><h3 id="六四-鸿渐于木-或得其桷-无咎。-象曰-或得其桷-顺以巽也。" tabindex="-1">六四，鸿渐于木，或得其桷，无咎。 象曰：“或得其桷”，顺以巽也。 <a class="header-anchor" href="#六四-鸿渐于木-或得其桷-无咎。-象曰-或得其桷-顺以巽也。" aria-label="Permalink to “六四，鸿渐于木，或得其桷，无咎。 象曰：“或得其桷”，顺以巽也。”">​</a></h3><p>木非鸿所居，如四之易位而在上也，然本坤之爻，进而为巽，故或得其桷，居之可安也。顺巽则众所与也，故得所安。</p><h3 id="九五-鸿渐于陵-妇三岁不孕-终莫之胜-吉。-象曰-终莫之胜吉-得所愿也。" tabindex="-1">九五，鸿渐于陵，妇三岁不孕，终莫之胜，吉。 象曰：“终莫之胜吉”，得所愿也。 <a class="header-anchor" href="#九五-鸿渐于陵-妇三岁不孕-终莫之胜-吉。-象曰-终莫之胜吉-得所愿也。" aria-label="Permalink to “九五，鸿渐于陵，妇三岁不孕，终莫之胜，吉。 象曰：“终莫之胜吉”，得所愿也。”">​</a></h3><h3 id="上九-鸿渐于陆-其羽可用为仪-吉。-象曰-其羽可用为仪吉-不可乱也。" tabindex="-1">上九，鸿渐于陆，其羽可用为仪，吉。 象曰：“其羽可用为仪吉”，不可乱也。 <a class="header-anchor" href="#上九-鸿渐于陆-其羽可用为仪-吉。-象曰-其羽可用为仪吉-不可乱也。" aria-label="Permalink to “上九，鸿渐于陆，其羽可用为仪，吉。 象曰：“其羽可用为仪吉”，不可乱也。”">​</a></h3><p>无应于下，羽洁无污，且处于高，故曰渐陆。</p>',16)])])}const b=e(l,[["render",t]]);export{_ as __pageData,b as default};
